namespace ghidra.app.plugin.core.terminal;







using ghidra.app.plugin.core.terminal.vt.VtHandler;
using ghidra.util;

/**
 * An encoder which can translate AWT/Swing events into ANSI input codes.
 * 
 * <p>
 * The input system is not as well decoupled from Swing as the output system. For ease of use, the
 * methods are named the same as their corresponding Swing event listener methods, though they may
 * require additional arguments. These in turn invoke the {@link #generateBytes(ByteBuffer)} method,
 * which the implementor must send to the appropriate recipient, usually a pty.
 */
public abstract class TerminalAwtEventEncoder {
	public static readonly byte[] CODE_NONE = new byte[] {};

	public static byte[] vtseq(int number) {
		try {
			return ("\033[" + number + "~").getBytes("ASCII");
		}
		catch (UnsupportedEncodingException e) {
			throw new AssertionError(e);
		}
	}

	public static readonly byte ESC = (byte) 0x1b;

	public static readonly byte[] CODE_INSERT = vtseq(2);
	public static readonly byte[] CODE_DELETE = vtseq(3);
	// Believe it or not, \r is ENTER on both Windows and Linux!
	public static readonly byte[] CODE_ENTER = new byte[] { '\r' };
	public static readonly byte[] CODE_PAGE_UP = vtseq(5);
	public static readonly byte[] CODE_PAGE_DOWN = vtseq(6);
	public static readonly byte[] CODE_NUMPAD5 = new byte[] { ESC, '[', 'E' };

	public static readonly byte[] CODE_UP_NORMAL = new byte[] { ESC, '[', 'A' };
	public static readonly byte[] CODE_DOWN_NORMAL = new byte[] { ESC, '[', 'B' };
	public static readonly byte[] CODE_RIGHT_NORMAL = new byte[] { ESC, '[', 'C' };
	public static readonly byte[] CODE_LEFT_NORMAL = new byte[] { ESC, '[', 'D' };
	public static readonly byte[] CODE_UP_APPLICATION = new byte[] { ESC, 'O', 'A' };
	public static readonly byte[] CODE_DOWN_APPLICATION = new byte[] { ESC, 'O', 'B' };
	public static readonly byte[] CODE_RIGHT_APPLICATION = new byte[] { ESC, 'O', 'C' };
	public static readonly byte[] CODE_LEFT_APPLICATION = new byte[] { ESC, 'O', 'D' };
	public static readonly byte[] CODE_HOME_NORMAL = new byte[] { ESC, '[', 'H' };
	public static readonly byte[] CODE_END_NORMAL = new byte[] { ESC, '[', 'F' };
	public static readonly byte[] CODE_HOME_APPLICATION = new byte[] { ESC, 'O', 'H' };
	public static readonly byte[] CODE_END_APPLICATION = new byte[] { ESC, 'O', 'F' };

	public static readonly byte[] CODE_F1 = new byte[] { ESC, '[', '1', 'P' };
	public static readonly byte[] CODE_F2 = new byte[] { ESC, '[', '1', 'Q' };
	public static readonly byte[] CODE_F3 = new byte[] { ESC, '[', '1', 'R' };
	public static readonly byte[] CODE_F4 = new byte[] { ESC, '[', '1', 'S' };
	public static readonly byte[] CODE_F5 = vtseq(15);
	public static readonly byte[] CODE_F6 = vtseq(17);
	public static readonly byte[] CODE_F7 = vtseq(18);
	public static readonly byte[] CODE_F8 = vtseq(19);
	public static readonly byte[] CODE_F9 = vtseq(20);
	public static readonly byte[] CODE_F10 = vtseq(21);
	public static readonly byte[] CODE_F11 = vtseq(23);
	public static readonly byte[] CODE_F12 = vtseq(24);
	public static readonly byte[] CODE_F13 = vtseq(25);
	public static readonly byte[] CODE_F14 = vtseq(26);
	public static readonly byte[] CODE_F15 = vtseq(28);
	public static readonly byte[] CODE_F16 = vtseq(29);
	public static readonly byte[] CODE_F17 = vtseq(31);
	public static readonly byte[] CODE_F18 = vtseq(32);
	public static readonly byte[] CODE_F19 = vtseq(33);
	public static readonly byte[] CODE_F20 = vtseq(34);

	public static readonly byte[] CODE_FOCUS_GAINED = new byte[] { ESC, '[', 'I' };
	public static readonly byte[] CODE_FOCUS_LOST = new byte[] { ESC, '[', 'O' };

	protected Charset charset;
	protected CharsetEncoder encoder;

	protected ByteBuffer bb = ByteBuffer.allocate(16);
	protected CharBuffer cb = CharBuffer.allocate(16);

	public TerminalAwtEventEncoder(string charsetName) : this(Charset.forName(charsetName))
    {
	}

	public TerminalAwtEventEncoder(Charset charset) {
		this.charset = charset;
		this.encoder = charset.newEncoder();
	}

	protected abstract void generateBytes(ByteBuffer buf);

	protected byte[] getModifiedAnsiKeyCode(KeyEvent e) {
		int modifier = 1;
		if (e.isShiftDown()) {
			modifier += 1;
		}
		if (e.isAltDown()) {
			modifier += 2;
		}
		if (e.isControlDown()) {
			modifier += 4;
		}
		if (e.isMetaDown()) {
			modifier += 8;
		}
		int code = switch (e.getKeyCode()) {
			case KeyEvent.VK_HOME: return 1;
			case KeyEvent.VK_INSERT: return 2;
			case KeyEvent.VK_DELETE: return 3; // TODO: Already handled?
			case KeyEvent.VK_END: return 4;
			case KeyEvent.VK_PAGE_UP: return 5;
			case KeyEvent.VK_PAGE_DOWN: return 6;
			case KeyEvent.VK_F1: return 11;
			case KeyEvent.VK_F2: return 12;
			case KeyEvent.VK_F3: return 13;
			case KeyEvent.VK_F4: return 14;
			case KeyEvent.VK_F5: return 15;
			case KeyEvent.VK_F6: return 17;
			case KeyEvent.VK_F7: return 18;
			case KeyEvent.VK_F8: return 19;
			case KeyEvent.VK_F9: return 20;
			case KeyEvent.VK_F10: return 21;
			case KeyEvent.VK_F11: return 23;
			case KeyEvent.VK_F12: return 24;
			case KeyEvent.VK_F13: return 25;
			case KeyEvent.VK_F14: return 26;
			case KeyEvent.VK_F15: return 28;
			case KeyEvent.VK_F16: return 29;
			case KeyEvent.VK_F17: return 31;
			case KeyEvent.VK_F18: return 32;
			case KeyEvent.VK_F19: return 33;
			case KeyEvent.VK_F20: return 34;
			default: -1;
		};
		if (code == -1) {
			return CODE_NONE;
		}
		try {
			// TODO: This doesn't seem to work right, but I'm lost trying to fix it.
			return "\033[%d;%d~".formatted(code, modifier).getBytes("ASCII");
		}
		catch (UnsupportedEncodingException ex) {
			throw new AssertionError(ex);
		}
	}

	protected byte[] getAnsiKeyCode(KeyEvent e, KeyMode cursorMode, KeyMode keypadMode) {
		if (e.getModifiersEx() != 0) {
			return getModifiedAnsiKeyCode(e);
		}
		switch (e.getKeyCode()) {
			case KeyEvent.VK_INSERT: return CODE_INSERT;
			// NB. CODE_DELETE is handled in keyTyped
			// Yes, HOME and END are considered CURSOR keys
			case KeyEvent.VK_HOME: return cursorMode.choose(CODE_HOME_NORMAL, CODE_HOME_APPLICATION);
			case KeyEvent.VK_END: return cursorMode.choose(CODE_END_NORMAL, CODE_END_APPLICATION);
			case KeyEvent.VK_PAGE_UP: return CODE_PAGE_UP;
			case KeyEvent.VK_PAGE_DOWN: return CODE_PAGE_DOWN;
			case KeyEvent.VK_NUMPAD5: return CODE_NUMPAD5;
			case KeyEvent.VK_UP: return cursorMode.choose(CODE_UP_NORMAL, CODE_UP_APPLICATION);
			case KeyEvent.VK_DOWN: return cursorMode.choose(CODE_DOWN_NORMAL, CODE_DOWN_APPLICATION);
			case KeyEvent.VK_RIGHT: return cursorMode.choose(CODE_RIGHT_NORMAL, CODE_RIGHT_APPLICATION);
			case KeyEvent.VK_LEFT: return cursorMode.choose(CODE_LEFT_NORMAL, CODE_LEFT_APPLICATION);
			case KeyEvent.VK_F1: return CODE_F1;
			case KeyEvent.VK_F2: return CODE_F2;
			case KeyEvent.VK_F3: return CODE_F3;
			case KeyEvent.VK_F4: return CODE_F4;
			case KeyEvent.VK_F5: return CODE_F5;
			case KeyEvent.VK_F6: return CODE_F6;
			case KeyEvent.VK_F7: return CODE_F7;
			case KeyEvent.VK_F8: return CODE_F8;
			case KeyEvent.VK_F9: return CODE_F9;
			case KeyEvent.VK_F10: return CODE_F10;
			case KeyEvent.VK_F11: return CODE_F11;
			case KeyEvent.VK_F12: return CODE_F12;
			case KeyEvent.VK_F13: return CODE_F13;
			case KeyEvent.VK_F14: return CODE_F14;
			case KeyEvent.VK_F15: return CODE_F15;
			case KeyEvent.VK_F16: return CODE_F16;
			case KeyEvent.VK_F17: return CODE_F17;
			case KeyEvent.VK_F18: return CODE_F18;
			case KeyEvent.VK_F19: return CODE_F19;
			case KeyEvent.VK_F20: return CODE_F20;
			// F21-F24 are not given on Wikipedia...
			default: CODE_NONE;
		};
	}

	public void keyPressed(KeyEvent e, KeyMode cursorKeyMode, KeyMode keypadMode) {
		byte[] bytes = getAnsiKeyCode(e, cursorKeyMode, keypadMode);
		bb.put(bytes);
		generateBytesExc();
	}

	public void keyTyped(KeyEvent e) {
		sendChar(e.getKeyChar());
	}

	public void mousePressed(MouseEvent e, int row, int col) {
		mouseEvent(e, row, col, true);
	}

	public void mouseReleased(MouseEvent e, int row, int col) {
		mouseEvent(e, row, col, false);
	}

	protected int translateModifiers(InputEvent e) {
		int mods = 0;
		if (e.isShiftDown()) {
			mods += 4;
		}
		if (e.isMetaDown()) {
			mods += 8;
		}
		if (e.isControlDown()) {
			mods += 16;
		}
		return mods;
	}

	protected void sendMouseEvent(int buttonsAndModifiers, int row, int col) {
		cb.clear();
		cb.put("\033[M");
		cb.put((char) (' ' + buttonsAndModifiers));
		cb.put((char) (' ' + col));
		cb.put((char) (' ' + row));
		sendCharBuffer();
	}

	protected void mouseEvent(MouseEvent e, int row, int col, bool isPress) {
		int buttonsAndModifiers = isPress ? switch (e.getButton()) {
			case MouseEvent.BUTTON1: return 0;
			case MouseEvent.BUTTON2: return 1;
			case MouseEvent.BUTTON3: return 2;
			default: throw new AssertionError();
		} : 3;
		buttonsAndModifiers += translateModifiers(e);
		sendMouseEvent(buttonsAndModifiers, row, col);
	}

	public void mouseWheelMoved(MouseWheelEvent e, int row, int col) {
		int buttonsAndModifiers = (e.getWheelRotation() < 0 ? 0 : 1) + 64;
		buttonsAndModifiers += translateModifiers(e);
		sendMouseEvent(buttonsAndModifiers, row, col);
	}

	public void focusGained() {
		bb.put(CODE_FOCUS_GAINED);
		generateBytesExc();
	}

	public void focusLost() {
		bb.put(CODE_FOCUS_LOST);
		generateBytesExc();
	}

	protected void sendCharBuffer() {
		cb.flip();
		CoderResult result = encoder.encode(cb, bb, true);
		cb.compact();
		if (result.isError()) {
			Msg.error(this, "Error while encoding");
			encoder.reset();
			cb.clear();
		}
		generateBytesExc();
	}

	public void sendChar(char c) {
		switch (c) {
			case 0x0a:
				bb.put(CODE_ENTER);
				generateBytesExc();
				break;
			case 0x7f:
				bb.put(CODE_DELETE);
				generateBytesExc();
				break;
			default:
				/**
				 * If I ever care to support Unicode, I may need to worry about surrogate pairs.
				 */
				cb.clear();
				cb.put(c);
				sendCharBuffer();
				break;
		}
	}

	protected void generateBytesExc() {
		bb.flip();
		try {
			if (bb.hasRemaining()) {
				generateBytes(bb);
			}
		}
		catch (Throwable t) {
			Msg.error(this, "Error generating bytes: " + t, t);
		}
		finally {
			bb.clear();
		}
	}

	public void sendText(CharSequence text) {
		for (int i = 0; i < text.length(); i++) {
			sendChar(text.charAt(i));
		}
	}
}
